using System;
using System.Linq;
using System.IO;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;

namespace Ara {
 public static class RoutineTests {
  static void Assert(bool yes,string why){if(!yes)throw new Exception(why);}
  static State New(){var s=State.New();s.AdaptivePriority=false;GridEngine.Ensure(s,s.GetDay(new DateTime(2026,10,14)));return s;}
  static Day D(State s){return s.Days[0];}
  static CellBlock Meal(GridPlan p,string id){return p.Blocks.Find(x=>x.MealId==id);}
  static void Record(Day d,string meal,DateTime start,int count=3){d.Records.Add(new CellBlock{Id="actual-"+meal,Start=start,Count=count,Category="식사",Name=meal,MealId=meal,Score=2});}
  static Point Center(TestBoard b,int lane,int index){var r=b.CellRect(lane,index);return new Point(r.X+r.Width/2,r.Y+r.Height/2);}
  static IEnumerable<Control> Children(Control c){foreach(Control child in c.Controls){yield return child;foreach(var nested in Children(child))yield return nested;}}
  public static void Run(Action<string,Action> check,string dir){
   check("routine: five meals and ten-minute prep exactly match requested starts",()=>{var s=New();var d=D(s);var p=GridEngine.Build(s,d);int[] minutes={30,270,450,750,930};Assert(p.Blocks.Count==14,"wake and 13 core blocks");for(int i=0;i<5;i++){var meal=Meal(p,Routine.MealIds[i]);Assert(meal.Start==d.Wake.AddMinutes(minutes[i])&&meal.Count==(i==4?1:3),"meal "+i);var prep=p.Blocks.Single(x=>x.PrepFor==meal.MealId);Assert(prep.End==meal.Start&&prep.Count==1,"prep "+i);}Assert(p.Blocks.Last().End==d.Wake.AddMinutes(940),"day end");});
   check("routine: zone2, shower, weights and gaps match wake-relative rules",()=>{var s=New();var d=D(s);var p=GridEngine.Build(s,d);var zone=p.Blocks.Single(x=>x.Category=="존2");var shower=p.Blocks.Single(x=>x.TemplateId=="b5");var weights=p.Blocks.Single(x=>x.Category=="웨이트");Assert(zone.Start==d.Wake.AddMinutes(150)&&zone.Count==4&&shower.Start==zone.End&&shower.Count==2,"zone/shower");Assert(weights.Start==Meal(p,"b10").Start.AddHours(2)&&weights.Count==12&&Meal(p,"b15").Start==weights.End.AddHours(1),"weights");Assert(!p.Blocks.Any(x=>x.Category=="작업"||x.Category=="학습"||x.Category=="휴식"),"blank gaps");Assert(!p.Blocks.Any(x=>GridEngine.Overlap(x,d.Wake.AddHours(1),d.Wake.AddHours(2))),"unassigned gap");});
   check("routine: late meal uses start-to-start intervals independent of eating duration",()=>{var s=New();var d=D(s);Record(d,"b1",d.Wake.AddMinutes(50),6);var p=GridEngine.Build(s,d);Assert(Meal(p,"b6").Start==d.Records[0].Start.AddHours(4),"four hours from start");Assert(Meal(p,"b10").Start==Meal(p,"b6").Start.AddHours(3),"three hours from start");Assert(d.Records[0].Count==6&&Meal(p,"b1").Count==3&&p.Saved==0,"actual duration remains factual");});
   check("routine: independent second meal anchor updates third meal and exercises",()=>{var s=New();var d=D(s);Record(d,"b1",d.Wake.AddMinutes(40));Record(d,"b6",d.Wake.AddMinutes(290));var p=GridEngine.Build(s,d);Assert(Meal(p,"b1").Start==d.Records[0].Start&&Meal(p,"b6").Start==d.Records[1].Start,"anchors fixed");Assert(Meal(p,"b10").Start==d.Records[1].Start.AddHours(3),"third");Assert(p.Blocks.Single(x=>x.Category=="웨이트").Start==Meal(p,"b10").Start.AddHours(2),"weights reflow");});
   check("routine: early meal pulls future forward and prep tracks meal",()=>{var s=New();var d=D(s);Record(d,"b6",d.Wake.AddMinutes(240));var p=GridEngine.Build(s,d);Assert(Meal(p,"b10").Start==d.Wake.AddMinutes(420),"third earlier");Assert(p.Blocks.Single(x=>x.PrepFor=="b6").End==d.Records[0].Start,"prep");});
   check("routine: large delay spends future exercise buffers and reports remaining delay",()=>{var s=New();var d=D(s);Record(d,"b1",d.Wake.AddMinutes(170));var p=GridEngine.Build(s,d);Assert(p.Saved==110&&p.Overflow==10,"110 recovered, 10 remains with shorter yogurt");Assert(p.Blocks.Single(x=>x.Category=="존2").Count==2&&p.Blocks.Single(x=>x.Category=="웨이트").Count==3,"minimums");Assert(d.Records.Single().Start==d.Wake.AddMinutes(170),"actual unchanged");});
   check("routine: late third meal does not shorten past zone2",()=>{var s=New();var d=D(s);Record(d,"b10",d.Wake.AddMinutes(550));var p=GridEngine.Build(s,d);Assert(p.Blocks.Single(x=>x.Category=="존2").Count==4,"past zone");Assert(p.Saved==80&&p.Overflow==0,"future weights only, twenty-minute headroom");});
   check("routine: early overlapping meal trims only unrecorded activity",()=>{var s=New();var d=D(s);Record(d,"b6",d.Wake.AddMinutes(200));var p=GridEngine.Build(s,d);for(int i=1;i<p.Blocks.Count;i++)Assert(p.Blocks[i].Start>=p.Blocks[i-1].End,"no overlap");Assert(p.Blocks.Single(x=>x.Category=="존2").Count==4&&!p.Blocks.Any(x=>x.TemplateId=="b5"),"overlapping shower removed");});
   check("routine: very early second meal removes preceding shower even if now after meal",()=>{var s=New();var d=D(s);Record(d,"b6",d.Wake.AddHours(3),4);var p=GridEngine.Build(s,d);Assert(Meal(p,"b6").Start==d.Wake.AddHours(3)&&Meal(p,"b10").Start==d.Wake.AddHours(6),"meal facts");Assert(p.Blocks.Single(x=>x.Category=="존2").Count==2&&!p.Blocks.Any(x=>x.TemplateId=="b5"),"early zone/shower trimmed");for(int i=1;i<p.Blocks.Count;i++)Assert(p.Blocks[i].Start>=p.Blocks[i-1].End,"no overlap");});
   check("routine: reversed actual meal order is rejected",()=>{var s=New();var d=D(s);Record(d,"b1",d.Wake.AddMinutes(300));Record(d,"b6",d.Wake.AddMinutes(200));bool rejected=false;try{GridEngine.Build(s,d);}catch(InvalidOperationException){rejected=true;}Assert(rejected,"meal ordering");});
   check("routine: upgrade preserves actual records, notes, tasks and historical plans",()=>{var s=State.Legacy();var past=s.GetDay(new DateTime(2026,10,13));GridEngine.Ensure(s,past);var old=past.GridBase.Last().End;var today=s.GetDay(new DateTime(2026,10,14));GridEngine.Ensure(s,today);Record(today,"b6",today.Wake.AddHours(4));today.Note="보존 메모";s.Tasks.Add(new Todo{Id="a",Text="보존 과제"});Routine.Upgrade(s,new DateTime(2026,10,14));Assert(s.ScheduleRevision==3&&today.StartAnchoredMeals&&!past.StartAnchoredMeals&&past.GridBase.Last().End==old,"upgrade boundaries");Assert(today.Records.Count==1&&today.Note=="보존 메모"&&s.Tasks.Count==1&&today.GridBase.Count==14,"preserved");new Store(Path.Combine(dir,"routine-upgrade.json")).Save(s);var loaded=new Store(Path.Combine(dir,"routine-upgrade.json")).Load();Assert(loaded.ScheduleRevision==3&&loaded.Days[1].Records[0].Count==3,"roundtrip");});
   check("routine: old actual starts migrate before replacing the default plan",()=>{var s=State.Legacy();var d=s.GetDay(new DateTime(2026,10,14));d.Actual["b1"]=d.Wake.AddMinutes(40);Routine.Upgrade(s,d.Wake.Date);Assert(d.Records.Single().Start==d.Wake.AddMinutes(40)&&d.Records.Single().MealId=="b1"&&d.GridBase.Count==14,"legacy start retained");Assert(Meal(GridEngine.Build(s,d),"b6").Start==d.Wake.AddMinutes(280),"new intervals");});
   check("assignment: planned action, decimal score and selected duration survive saving",()=>{var s=New();var d=D(s);var p=GridEngine.Build(s,d);var source=p.Blocks.Single(x=>x.Category=="웨이트");source.Score=4.25m;using(var dialog=new AssignmentDialog(new CellSelection{Lane=1,First=105,Last=113},d.Wake.Date.AddHours(17).AddMinutes(30),source,p.Blocks)){dialog.Show();Application.DoEvents();Children(dialog).OfType<TextBox>().Single(x=>x.MaxLength==250).Text="";Children(dialog).OfType<Button>().Single(x=>x.Text=="저장").PerformClick();Assert(dialog.Result!=null&&dialog.Result.Category=="웨이트"&&dialog.Result.Name==""&&dialog.Result.Count==9&&dialog.Result.Score*9==38.25m&&source.Count==12,"assignment payload");}});
   check("pointer: clicking a selected range opens assignment without collapsing selection",()=>{using(var f=new Form{Size=new Size(900,650)})using(var b=new TestBoard()){f.Controls.Add(b);f.Show();Application.DoEvents();b.SetData(new DateTime(2026,10,14),new List<CellBlock>(),new List<CellBlock>());int edits=0;b.EditRequested+=(s,e)=>edits++;b.SimulateDrag(1,51,72,true);Assert(edits==0,"drag does not open");b.Jump(b.TimeAt(60));var point=Center(b,1,61);b.Down(point);b.Drag(new Point(point.X+1,point.Y+1));b.Up(point);Assert(edits==1&&b.Selection.First==51&&b.Selection.Last==72,"reclick retains all cells");f.Close();}});
   check("pointer: plan-to-actual copy uses source action at same time",()=>{using(var f=new Form{Size=new Size(900,650)})using(var b=new TestBoard()){f.Controls.Add(b);f.Show();Application.DoEvents();var origin=new DateTime(2026,10,14);var plan=new CellBlock{Id="p",Start=origin.AddHours(8).AddMinutes(30),Count=3,Name="1끼니",Category="식사",MealId="b1"};b.SetData(origin,new List<CellBlock>{plan},new List<CellBlock>());b.Jump(origin.AddHours(8));PaletteRequest copy=null;b.PaletteRequested+=(s,e)=>copy=e;b.Down(Center(b,0,52));b.Drag(Center(b,1,52));b.Up(Center(b,1,52));Assert(copy!=null&&copy.Selection.First==51&&copy.Selection.Count==3&&copy.Item.MealId=="b1"&&plan.Start==origin.AddHours(8).AddMinutes(30),"source copy");f.Close();}});
   check("pointer: actual blocks cannot move into upper plan lane",()=>{using(var f=new Form{Size=new Size(900,650)})using(var b=new TestBoard()){f.Controls.Add(b);f.Show();Application.DoEvents();var origin=new DateTime(2026,10,14);b.SetData(origin,new List<CellBlock>(),new List<CellBlock>{new CellBlock{Id="a",Start=origin.AddHours(8),Count=3,Category="작업"}});b.Jump(origin.AddHours(8));MoveRequest move=null;PaletteRequest copy=null;b.MoveRequested+=(s,e)=>move=e;b.PaletteRequested+=(s,e)=>copy=e;b.Down(Center(b,1,48));b.Drag(Center(b,0,54));b.Up(Center(b,0,54));Assert(move!=null&&move.Lane==1&&copy==null&&b.Selection.Lane==1,"actual lane retained");f.Close();}});
   check("wheel: repeated scrolling preserves a single stationary header",()=>{using(var f=new Form{Size=new Size(900,650)})using(var b=new TestBoard()){f.Controls.Add(b);f.Show();Application.DoEvents();var s=New();var d=D(s);b.SetData(d.Wake.Date,GridEngine.Build(s,d).Blocks,d.Records);b.Jump(d.Wake.AddHours(-1));using(var before=new Bitmap(b.Width,b.Height))using(var after=new Bitmap(b.Width,b.Height)){b.DrawToBitmap(before,new Rectangle(Point.Empty,b.Size));int offset=b.AutoScrollPosition.Y;for(int i=0;i<12;i++){b.Wheel(-120);Application.DoEvents();}Assert(b.AutoScrollPosition.Y<offset,"scroll changed");b.DrawToBitmap(after,new Rectangle(Point.Empty,b.Size));for(int y=0;y<Timetable.Header;y++)for(int x=0;x<b.Width;x++)Assert(before.GetPixel(x,y)==after.GetPixel(x,y),"header stationary");after.Save(Path.Combine(dir,"wheel-smoke.png"));for(int i=0;i<12;i++)b.Wheel(120);Assert(b.AutoScrollPosition.Y==offset,"reverse offset");}f.Close();}});
  }
 }
}
